## Service Methods

```typescript
class ContentModuleService extends MedusaService({ Review, ReviewImage, ProductReviewStats, FAQ }) {

  // Get reviews for product (store API)
  async getProductReviews(productId: string): Promise<{
    reviews: Review[]
    stats: ProductReviewStats | null
  }> {
    const [reviews, stats] = await Promise.all([
      this.listReviews(
        { product_id: productId, is_active: true },
        { order: { sort_order: 'ASC' }, relations: ['images'] }
      ),
      this.retrieveProductReviewStats({ product_id: productId }).catch(() => null)
    ])
    return { reviews, stats }
  }

  // Admin: Create review with images
  async createReviewWithImages(data: CreateReviewInput, imageUrls: string[]): Promise<Review> {
    const review = await this.createReviews(data)

    for (let i = 0; i < imageUrls.length; i++) {
      await this.createReviewImages({
        review_id: review.id,
        url: imageUrls[i],
        sort_order: i
      })
    }

    return this.retrieveReview(review.id, { relations: ['images'] })
  }

  // Admin: Update stats for a product
  async upsertProductStats(productId: string, stats: Partial<ProductReviewStats>): Promise<void> {
    const existing = await this.retrieveProductReviewStats({ product_id: productId }).catch(() => null)

    if (existing) {
      await this.updateProductReviewStats(existing.id, stats)
    } else {
      await this.createProductReviewStats({ product_id: productId, ...stats })
    }
  }
}
```

## Admin UI Requirements
- Product page widget showing review stats + 'Manage Reviews' button
- Review list page with add/edit/delete
- Review form: name, rating (star picker), title, content, verified checkbox, date picker, helpful count
- Image upload with S3 integration (immediate upload)
- Stats editor: average rating, total count, distribution bars

## Acceptance Criteria
- [ ] Review model with admin-controlled fields
- [ ] ReviewImage model for S3 images
- [ ] ProductReviewStats model for manual stats
- [ ] Service methods for CRUD operations
- [ ] No customer-facing submission endpoint
- [ ] Admin can set custom display dates
- [ ] Admin can set helpful counts manually
- [ ] Images upload to S3
- [ ] Unit tests for service methods

## Context

Add proper loading states, error handling, and edge case handling across all Express Checkout components. This ensures a polished user experience with clear feedback during payment processing.

**Blocked by:** EXP-005 (Checkout Integration)

---

## Files to Modify

- `src/modules/checkout/components/express-checkout/index.tsx`
- `src/modules/checkout/components/express-checkout/express-checkout-button.tsx`
- `src/modules/products/components/express-checkout-product/index.tsx`

---

## 1. Loading Skeleton Component

Add a loading skeleton while Stripe loads:

```typescript
// In express-checkout/index.tsx
const [isReady, setIsReady] = useState(false)

// Pass callback to button to track readiness
<ExpressCheckoutButton 
  cart={cart} 
  onReady={() => setIsReady(true)}
/>

// Show skeleton while loading
if (!isReady) {
  return (
    <div className="bg-white">
      <div className="h-6 w-40 bg-gray-200 rounded animate-pulse mb-4" />
      <div className="h-12 w-full bg-gray-200 rounded animate-pulse" />
    </div>
  )
}
```

---

## 2. Timeout Handling

Add timeout for slow Stripe connections:

```typescript
useEffect(() => {
  const timeout = setTimeout(() => {
    if (!isReady) {
      setLoadError(true)
      console.error("Express Checkout failed to load within timeout")
    }
  }, 10000) // 10 second timeout

  return () => clearTimeout(timeout)
}, [isReady])

// If timeout exceeded, hide component gracefully
if (loadError) {
  return null // Silently fall back to card payment
}
```

---

## 3. User-Friendly Error Messages

Create an error message mapper for Stripe errors:

```typescript
const getErrorMessage = (stripeError: any): string => {
  switch (stripeError.code) {
    case "card_declined":
      return "Your card was declined. Please try a different payment method."
    case "expired_card":
      return "Your card has expired. Please use a different card."
    case "incorrect_cvc":
      return "The security code is incorrect. Please check and try again."
    case "processing_error":
      return "An error occurred while processing. Please try again."
    case "insufficient_funds":
      return "Insufficient funds. Please try a different payment method."
    case "payment_intent_authentication_failure":
      return "Authentication failed. Please try again."
    default:
      return stripeError.message || "Payment failed. Please try again."
  }
}

// Usage in onConfirm:
if (error) {
  setErrorMessage(getErrorMessage(error))
  setIsProcessing(false)
  return
}
```

---

## 4. No Express Methods Available

Handle case where no express payment methods are available:

```typescript
// In ExpressCheckoutButton
const onReady = useCallback(
  ({ availablePaymentMethods }: StripeExpressCheckoutElementReadyEvent) => {
    const hasExpressMethods =
      availablePaymentMethods?.applePay ||
      availablePaymentMethods?.googlePay ||
      availablePaymentMethods?.link ||
      availablePaymentMethods?.paypal

    setIsAvailable(!!hasExpressMethods)

    // Notify parent component
    onReady?.()

    if (!hasExpressMethods) {
      // Log for debugging but don't show error to user
      console.log("No express payment methods available for this browser/device")
    }
  },
  [onReady]
)

// Component returns null when not available - user just sees card form
if (!isAvailable) {
  return null
}
```

---

## 5. Processing State UI

Show clear processing indicator:

```typescript
{isProcessing && (
  <div className="flex items-center justify-center gap-2 mt-2">
    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-gray-900"></div>
    <p className="text-ui-fg-muted text-sm">
      Processing payment...
    </p>
  </div>
)}
```

---

## 6. Network Error Handling

Handle network failures gracefully:

```typescript
const onConfirm = useCallback(
  async (event: StripeExpressCheckoutElementConfirmEvent) => {
    // ... existing code ...

    try {
      // ... payment confirmation ...
    } catch (err: any) {
      console.error("Express checkout error:", err)

      // Check for network errors
      if (err.name === "NetworkError" || !navigator.onLine) {
        setErrorMessage("Network error. Please check your connection and try again.")
      } else if (err.message?.includes("timeout")) {
        setErrorMessage("Request timed out. Please try again.")
      } else {
        setErrorMessage(err.message || "An unexpected error occurred.")
      }
    } finally {
      setIsProcessing(false)
    }
  },
  [stripe, elements, clientSecret, cart]
)
```

---

## 7. Retry Mechanism

Allow users to retry after error:

```typescript
{errorMessage && (
  <div className="mt-2 text-center">
    <p className="text-red-500 text-sm">{errorMessage}</p>
    <button
      onClick={() => setErrorMessage(null)}
      className="text-sm text-blue-600 hover:underline mt-1"
    >
      Try again
    </button>
  </div>
)}
```

---

## Error Scenarios to Handle

| Scenario | User Message |
|----------|--------------|
| Card declined | "Your card was declined. Please try a different payment method." |
| Expired card | "Your card has expired. Please use a different card." |
| Insufficient funds | "Insufficient funds. Please try a different payment method." |
| Auth failed | "Authentication failed. Please try again." |
| Network error | "Network error. Please check your connection and try again." |
| Timeout | "Request timed out. Please try again." |
| No shipping | "We can't ship to this address. Please try a different address." |
| Generic error | "Payment failed. Please try again." |

---

## Acceptance Criteria

- [ ] Loading skeleton shown while Stripe loads
- [ ] 10-second timeout with graceful fallback
- [ ] User-friendly error messages (not raw Stripe errors)
- [ ] Graceful handling when no express methods available
- [ ] Clear processing indicator during payment
- [ ] Network error handling
- [ ] Retry button after errors
- [ ] All errors logged to console for debugging

## Overview
Create a custom React hook to manage image gallery state including current image index, navigation functions, and keyboard/touch event handlers.

## File to Create
```
table-clay-storefront/src/lib/hooks/use-image-gallery.tsx
```

## Hook Interface
```typescript
interface UseImageGalleryOptions {
  images: { id: string; url: string }[]
  initialIndex?: number
  enableKeyboard?: boolean  // Enable arrow key navigation
  enableSwipe?: boolean     // Enable touch swipe gestures
  onIndexChange?: (index: number) => void
}

interface UseImageGalleryReturn {
  // State
  currentIndex: number
  currentImage: { id: string; url: string } | null
  totalImages: number

  // Navigation
  goToIndex: (index: number) => void
  goToNext: () => void
  goToPrevious: () => void

  // Helpers
  isFirst: boolean
  isLast: boolean

  // Event handlers (to attach to elements)
  containerRef: React.RefObject<HTMLDivElement>  // For keyboard focus
  swipeHandlers: {
    onTouchStart: (e: TouchEvent) => void
    onTouchEnd: (e: TouchEvent) => void
  }
}
```

## Implementation Requirements

### 1. State Management
```typescript
const [currentIndex, setCurrentIndex] = useState(initialIndex || 0)

// Ensure index stays within bounds
const safeSetIndex = (index: number) => {
  const bounded = Math.max(0, Math.min(index, images.length - 1))
  setCurrentIndex(bounded)
  onIndexChange?.(bounded)
}
```

### 2. Navigation Functions
```typescript
const goToNext = useCallback(() => {
  if (currentIndex < images.length - 1) {
    safeSetIndex(currentIndex + 1)
  }
}, [currentIndex, images.length])

const goToPrevious = useCallback(() => {
  if (currentIndex > 0) {
    safeSetIndex(currentIndex - 1)
  }
}, [currentIndex])

const goToIndex = useCallback((index: number) => {
  safeSetIndex(index)
}, [])
```

### 3. Keyboard Navigation
```typescript
useEffect(() => {
  if (!enableKeyboard) return

  const handleKeyDown = (e: KeyboardEvent) => {
    // Only handle if gallery container or child is focused
    if (!containerRef.current?.contains(document.activeElement)) return

    if (e.key === 'ArrowRight') {
      e.preventDefault()
      goToNext()
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault()
      goToPrevious()
    }
  }

  window.addEventListener('keydown', handleKeyDown)
  return () => window.removeEventListener('keydown', handleKeyDown)
}, [enableKeyboard, goToNext, goToPrevious])
```

### 4. Touch/Swipe Detection
```typescript
const touchStartX = useRef<number | null>(null)
const SWIPE_THRESHOLD = 50 // minimum pixels to trigger swipe

const swipeHandlers = useMemo(() => ({
  onTouchStart: (e: TouchEvent) => {
    touchStartX.current = e.touches[0].clientX
  },
  onTouchEnd: (e: TouchEvent) => {
    if (touchStartX.current === null) return

    const touchEndX = e.changedTouches[0].clientX
    const diff = touchStartX.current - touchEndX

    if (Math.abs(diff) > SWIPE_THRESHOLD) {
      if (diff > 0) {
        goToNext()  // Swipe left = next
      } else {
        goToPrevious()  // Swipe right = previous
      }
    }

    touchStartX.current = null
  }
}), [goToNext, goToPrevious])
```

### 5. Handle Empty/Single Image Cases
```typescript
// Return early for edge cases
if (!images || images.length === 0) {
  return {
    currentIndex: -1,
    currentImage: null,
    totalImages: 0,
    goToIndex: () => {},
    goToNext: () => {},
    goToPrevious: () => {},
    isFirst: true,
    isLast: true,
    containerRef,
    swipeHandlers: { onTouchStart: () => {}, onTouchEnd: () => {} }
  }
}
```

## Testing Considerations
- Test with 0, 1, 2, and 10+ images
- Test keyboard navigation only fires when gallery is focused
- Test swipe detection threshold (not triggering on small movements)
- Test index bounds (cannot go below 0 or above length-1)

