## Context
Display "ORDER IN 22h 15m & GET IT BY WED, JAN 15" with live countdown. Creates urgency to order before cutoff time.

**Blocked By:** None (frontend only)

## File to Create

### table-clay-storefront/src/modules/products/components/delivery-countdown/index.tsx
```typescript
"use client"

import { useState, useEffect } from "react"
import { Truck, RotateCcw } from "lucide-react"

interface DeliveryCountdownProps {
  cutoffHour?: number      // default 14 (2PM local)
  deliveryDays?: number    // default 3 business days
  returnDays?: number      // default 30
  className?: string
}

// Skip weekends for delivery date calculation
const addBusinessDays = (date: Date, days: number): Date => {
  const result = new Date(date)
  let added = 0
  while (added < days) {
    result.setDate(result.getDate() + 1)
    const day = result.getDay()
    if (day !== 0 && day !== 6) { // Skip Sun (0) and Sat (6)
      added++
    }
  }
  return result
}

const formatDate = (date: Date): string => {
  return date.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
  }).toUpperCase()
}

const DeliveryCountdown = ({
  cutoffHour = 14,
  deliveryDays = 3,
  returnDays = 30,
  className = "",
}: DeliveryCountdownProps) => {
  const [timeLeft, setTimeLeft] = useState({ hours: 0, minutes: 0 })
  const [deliveryDate, setDeliveryDate] = useState("")
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)

    const calculateTime = () => {
      const now = new Date()
      const cutoff = new Date()
      cutoff.setHours(cutoffHour, 0, 0, 0)

      // If past cutoff, set to next day cutoff
      if (now > cutoff) {
        cutoff.setDate(cutoff.getDate() + 1)
      }

      const diff = cutoff.getTime() - now.getTime()
      const hours = Math.floor(diff / (1000 * 60 * 60))
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))

      setTimeLeft({ hours, minutes })

      // Calculate delivery date from cutoff (or next day if past)
      const shipDate = now > cutoff ? new Date(cutoff) : now
      const delivery = addBusinessDays(shipDate, deliveryDays)
      setDeliveryDate(formatDate(delivery))
    }

    calculateTime()
    const interval = setInterval(calculateTime, 60000) // Update every minute

    return () => clearInterval(interval)
  }, [cutoffHour, deliveryDays])

  if (!mounted) return null

  return (
    <div className={`space-y-2 ${className}`}>
      {/* Delivery countdown */}
      <div className="flex items-center gap-2 text-sm">
        <Truck className="w-4 h-4 text-amber-600" />
        <span>
          Order in{" "}
          <span className="font-bold text-red-600">{timeLeft.hours}h {timeLeft.minutes}m</span>
          {" "}& get it by{" "}
          <span className="font-bold">{deliveryDate}</span>
        </span>
      </div>

      {/* Return policy */}
      <div className="flex items-center gap-2 text-sm text-ui-fg-subtle">
        <RotateCcw className="w-4 h-4 text-amber-600" />
        <span>{returnDays}-Day Easy Returns</span>
      </div>
    </div>
  )
}

export default DeliveryCountdown
```

