## Implementation Code Structure

```typescript
import { useRef, useState, useEffect } from "react"
import Image from "next/image"
import { ChevronLeftIcon, ChevronRightIcon } from "@heroicons/react/24/outline"
import clx from "clx"

interface ThumbnailStripProps {
  images: { id: string; url: string }[]
  currentIndex: number
  onSelect: (index: number) => void
}

const THUMBNAIL_SIZE = 80
const THUMBNAIL_GAP = 12
const SCROLL_AMOUNT = 3 // Number of thumbnails to scroll

const ThumbnailStrip = ({ images, currentIndex, onSelect }: ThumbnailStripProps) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const [canScrollLeft, setCanScrollLeft] = useState(false)
  const [canScrollRight, setCanScrollRight] = useState(false)

  // Check scroll position to show/hide arrows
  const updateScrollButtons = () => {
    const container = scrollContainerRef.current
    if (!container) return

    setCanScrollLeft(container.scrollLeft > 0)
    setCanScrollRight(
      container.scrollLeft < container.scrollWidth - container.clientWidth - 1
    )
  }

  useEffect(() => {
    updateScrollButtons()
    const container = scrollContainerRef.current
    container?.addEventListener('scroll', updateScrollButtons)
    window.addEventListener('resize', updateScrollButtons)

    return () => {
      container?.removeEventListener('scroll', updateScrollButtons)
      window.removeEventListener('resize', updateScrollButtons)
    }
  }, [images.length])

  // Scroll to selected thumbnail when it changes
  useEffect(() => {
    const container = scrollContainerRef.current
    if (!container) return

    const thumbnail = container.children[currentIndex] as HTMLElement
    if (thumbnail) {
      thumbnail.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest',
        inline: 'center'
      })
    }
  }, [currentIndex])

  const scrollLeft = () => {
    const container = scrollContainerRef.current
    if (!container) return

    container.scrollBy({
      left: -(THUMBNAIL_SIZE + THUMBNAIL_GAP) * SCROLL_AMOUNT,
      behavior: 'smooth'
    })
  }

  const scrollRight = () => {
    const container = scrollContainerRef.current
    if (!container) return

    container.scrollBy({
      left: (THUMBNAIL_SIZE + THUMBNAIL_GAP) * SCROLL_AMOUNT,
      behavior: 'smooth'
    })
  }

  if (images.length <= 1) {
    return null // Don't show thumbnails for single image
  }

  return (
    <div className="relative flex items-center mt-4">
      {/* Left scroll arrow */}
      <button
        onClick={scrollLeft}
        className={clx(
          "flex-shrink-0 w-8 h-8 rounded-full",
          "bg-white shadow-md",
          "flex items-center justify-center",
          "transition-opacity duration-200",
          "mr-2",
          { "opacity-0 pointer-events-none": !canScrollLeft }
        )}
        aria-label="Scroll thumbnails left"
      >
        <ChevronLeftIcon className="w-4 h-4" />
      </button>

      {/* Thumbnail container */}
      <div
        ref={scrollContainerRef}
        className="flex gap-3 overflow-x-auto scrollbar-hide scroll-smooth"
        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
      >
        {images.map((image, index) => (
          <button
            key={image.id}
            onClick={() => onSelect(index)}
            className={clx(
              "flex-shrink-0 relative overflow-hidden rounded-md",
              "w-20 h-20 small:w-20 small:h-20",  // 80px
              "transition-all duration-200",
              "focus:outline-none focus:ring-2 focus:ring-ui-fg-base",
              {
                "ring-2 ring-ui-fg-base": index === currentIndex,
                "hover:ring-1 hover:ring-ui-fg-subtle": index !== currentIndex,
                "opacity-70 hover:opacity-100": index !== currentIndex,
              }
            )}
            aria-label={`View image ${index + 1}`}
            aria-current={index === currentIndex ? 'true' : undefined}
          >
            <Image
              src={image.url}
              alt={`Thumbnail ${index + 1}`}
              fill
              className="object-cover"
              sizes="80px"
            />
          </button>
        ))}
      </div>

      {/* Right scroll arrow */}
      <button
        onClick={scrollRight}
        className={clx(
          "flex-shrink-0 w-8 h-8 rounded-full",
          "bg-white shadow-md",
          "flex items-center justify-center",
          "transition-opacity duration-200",
          "ml-2",
          { "opacity-0 pointer-events-none": !canScrollRight }
        )}
        aria-label="Scroll thumbnails right"
      >
        <ChevronRightIcon className="w-4 h-4" />
      </button>
    </div>
  )
}

export default ThumbnailStrip
```

