## File to Create

```
table-clay-storefront/src/modules/products/components/express-checkout-product/index.tsx
```

---

## Full Implementation

```typescript
"use client"

import { useState, useCallback, useEffect } from "react"
import { loadStripe } from "@stripe/stripe-js"
import {
  Elements,
  ExpressCheckoutElement,
  useStripe,
  useElements,
} from "@stripe/react-stripe-js"
import { HttpTypes } from "@medusajs/types"
import {
  addToCart,
  initiatePaymentSession,
  updateCart,
  placeOrder,
  retrieveCart,
} from "@lib/data/cart"
import { listCartShippingMethods, setShippingMethod } from "@lib/data/fulfillment"

const stripePromise = loadStripe(
  process.env.NEXT_PUBLIC_STRIPE_KEY as string
)

interface ProductExpressCheckoutProps {
  product: HttpTypes.StoreProduct
  variant: HttpTypes.StoreProductVariant | undefined
  region: HttpTypes.StoreRegion
  disabled?: boolean
}

// Inner component that uses Stripe hooks (must be inside Elements provider)
const ProductExpressCheckoutInner: React.FC<{
  product: HttpTypes.StoreProduct
  variant: HttpTypes.StoreProductVariant
  region: HttpTypes.StoreRegion
  clientSecret: string
  cartId: string
}> = ({ product, variant, region, clientSecret, cartId }) => {
  const stripe = useStripe()
  const elements = useElements()
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [isProcessing, setIsProcessing] = useState(false)

  const onClick = useCallback(
    ({ resolve }: any) => {
      const price = variant.calculated_price?.calculated_amount || 0

      resolve({
        emailRequired: true,
        shippingAddressRequired: true,
        allowedShippingCountries: region.countries?.map(
          (c) => c.iso_2?.toUpperCase()
        ) || ["US"],
        lineItems: [
          {
            name: product.title || "Product",
            amount: price,
          },
        ],
      })
    },
    [product, variant, region]
  )

  const onShippingAddressChange = useCallback(
    async ({ address, resolve, reject }: any) => {
      try {
        // Update cart with shipping address
        await updateCart({
          shipping_address: {
            first_name: address.name?.split(" ")[0] || "",
            last_name: address.name?.split(" ").slice(1).join(" ") || "",
            address_1: address.line1 || "",
            address_2: address.line2 || "",
            city: address.city || "",
            province: address.state || "",
            postal_code: address.postal_code || "",
            country_code: address.country?.toLowerCase() || "",
          },
        })

        // Get shipping options for this address
        const shippingOptions = await listCartShippingMethods(cartId)

        const shippingRates = shippingOptions?.map((opt) => ({
          id: opt.id,
          displayName: opt.name,
          amount: opt.amount || 0,
        })) || []

        if (shippingRates.length === 0) {
          reject({ message: "No shipping options available for this address" })
          return
        }

        resolve({ shippingRates })
      } catch (error) {
        reject()
      }
    },
    [cartId]
  )

  const onShippingRateChange = useCallback(
    async ({ shippingRate, resolve, reject }: any) => {
      try {
        await setShippingMethod({
          cartId,
          shippingMethodId: shippingRate.id,
        })
        resolve()
      } catch (error) {
        reject()
      }
    },
    [cartId]
  )

  const onConfirm = useCallback(
    async (event: any) => {
      if (!stripe || !elements) return

      setIsProcessing(true)
      setErrorMessage(null)

      try {
        const { error, paymentIntent } = await stripe.confirmPayment({
          elements,
          clientSecret,
          confirmParams: {
            return_url: `${window.location.origin}/${region.countries?.[0]?.iso_2 || "us"}/order/confirmed`,
            payment_method_data: {
              billing_details: event.billingDetails,
            },
          },
          redirect: "if_required",
        })

        if (error) {
          setErrorMessage(error.message || "Payment failed")
          setIsProcessing(false)
          return
        }

        if (
          paymentIntent?.status === "succeeded" ||
          paymentIntent?.status === "requires_capture"
        ) {
          await placeOrder(cartId)
        }
      } catch (err: any) {
        setErrorMessage(err.message || "An error occurred")
        setIsProcessing(false)
      }
    },
    [stripe, elements, clientSecret, cartId, region]
  )

  return (
    <div className="mt-4">
      <ExpressCheckoutElement
        options={{
          buttonTheme: { applePay: "black", googlePay: "black" },
          buttonType: { applePay: "buy", googlePay: "buy" },
          buttonHeight: 44,
          layout: { maxColumns: 2, maxRows: 1 },
        }}
        onClick={onClick}
        onShippingAddressChange={onShippingAddressChange}
        onShippingRateChange={onShippingRateChange}
        onConfirm={onConfirm}
        onCancel={() => setErrorMessage(null)}
      />
      {errorMessage && (
        <p className="text-red-500 text-sm mt-2">{errorMessage}</p>
      )}
    </div>
  )
}

// Outer component that sets up cart and payment session
const ProductExpressCheckout: React.FC<ProductExpressCheckoutProps> = ({
  product,
  variant,
  region,
  disabled,
}) => {
  const [clientSecret, setClientSecret] = useState<string | null>(null)
  const [cartId, setCartId] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  // Setup cart and payment session when variant is selected
  useEffect(() => {
    if (!variant || disabled) return

    const setupPayment = async () => {
      setIsLoading(true)
      try {
        // Add item to cart (creates cart if needed)
        await addToCart({
          variantId: variant.id,
          quantity: 1,
          countryCode: region.countries?.[0]?.iso_2 || "us",
        })

        // Get the cart
        const cart = await retrieveCart()
        if (!cart) return

        setCartId(cart.id)

        // Initiate payment session
        const result = await initiatePaymentSession(cart, {
          provider_id: "pp_stripe_stripe",
        })

        if (result?.payment_collection?.payment_sessions?.[0]?.data?.client_secret) {
          setClientSecret(
            result.payment_collection.payment_sessions[0].data.client_secret as string
          )
        }
      } catch (error) {
        console.error("Error setting up express checkout:", error)
      } finally {
        setIsLoading(false)
      }
    }

    setupPayment()
  }, [variant, region, disabled])

  if (!variant || disabled || !clientSecret || !cartId) {
    return null
  }

  return (
    <Elements
      stripe={stripePromise}
      options={{
        clientSecret,
        appearance: {
          theme: "stripe",
        },
      }}
    >
      <ProductExpressCheckoutInner
        product={product}
        variant={variant}
        region={region}
        clientSecret={clientSecret}
        cartId={cartId}
      />
    </Elements>
  )
}

export default ProductExpressCheckout
```

