## Context
Background job to clean up orphaned S3 images. When admin uploads images but doesn't save the record, or deletes a record, images may be left in S3. This job removes them after 30 days.

**Reference Images:** N/A (backend infrastructure)

## Key Decisions (from requirements interview)

| Decision | Choice |
|----------|--------|
| Cleanup period | 30 days |
| Upload timing | Immediate (images uploaded before record saved) |

## How Orphans Occur

1. **Upload without save:** Admin uploads images, then navigates away without saving
2. **Record deletion:** Admin deletes bundle/review, but S3 images remain
3. **Image replacement:** Admin removes image from record but doesn't delete from S3

## Implementation

### table-clay-store/src/jobs/s3-orphan-cleanup.ts

```typescript
import { MedusaContainer } from '@medusajs/framework'
import { S3Client, ListObjectsV2Command, DeleteObjectCommand } from '@aws-sdk/client-s3'

export default async function s3OrphanCleanupJob(container: MedusaContainer) {
  const contentModule = container.resolve('contentModuleService')
  const logger = container.resolve('logger')

  const s3Client = new S3Client({
    region: process.env.S3_REGION,
    credentials: {
      accessKeyId: process.env.S3_ACCESS_KEY_ID!,
      secretAccessKey: process.env.S3_SECRET_ACCESS_KEY!,
    },
  })

  const BUCKET = process.env.S3_BUCKET!
  const ORPHAN_AGE_DAYS = 30
  const cutoffDate = new Date()
  cutoffDate.setDate(cutoffDate.getDate() - ORPHAN_AGE_DAYS)

  logger.info('Starting S3 orphan cleanup job')

  // 1. Get all S3 objects in uploads/ prefix
  const s3Objects = await listAllS3Objects(s3Client, BUCKET, 'uploads/')

  // 2. Get all image URLs currently referenced in database
  const reviewImages = await contentModule.listReviewImages({})
  // Add bundle images when implemented

  const referencedUrls = new Set([
    ...reviewImages.map(img => img.url),
  ])

  // 3. Find orphans (in S3 but not in DB, older than cutoff)
  let deletedCount = 0

  for (const obj of s3Objects) {
    const s3Url = `https://${BUCKET}.s3.${process.env.S3_REGION}.amazonaws.com/${obj.Key}`

    if (!referencedUrls.has(s3Url) && obj.LastModified < cutoffDate) {
      // This is an orphan - delete it
      await s3Client.send(new DeleteObjectCommand({
        Bucket: BUCKET,
        Key: obj.Key,
      }))
      deletedCount++
      logger.debug(`Deleted orphan: ${obj.Key}`)
    }
  }

  logger.info(`S3 orphan cleanup complete. Deleted ${deletedCount} orphaned files.`)
}

async function listAllS3Objects(client: S3Client, bucket: string, prefix: string) {
  const objects: { Key: string, LastModified: Date }[] = []
  let continuationToken: string | undefined

  do {
    const response = await client.send(new ListObjectsV2Command({
      Bucket: bucket,
      Prefix: prefix,
      ContinuationToken: continuationToken,
    }))

    if (response.Contents) {
      objects.push(...response.Contents.map(obj => ({
        Key: obj.Key!,
        LastModified: obj.LastModified!,
      })))
    }

    continuationToken = response.NextContinuationToken
  } while (continuationToken)

  return objects
}

export const config = {
  name: 's3-orphan-cleanup',
  schedule: '0 3 * * 0',  // Run at 3 AM every Sunday
}
```

