class StoreSettingsModuleService extends MedusaService({ StoreSetting }) {

  // Get a single setting by key
  async getSetting(key: string): Promise<string | null> {
    const setting = await this.retrieveStoreSetting({ key }).catch(() => null)
    return setting?.value ?? null
