```typescript
"use client"

import { useState, useEffect } from "react"

interface UrgencyIndicatorProps {
  productId: string
  minViewers?: number  // default 3
  maxViewers?: number  // default 15
  className?: string
}

// Generate consistent random based on productId + time block
// Changes every 30 seconds for subtle variation
const generateViewerCount = (
  productId: string, 
  minViewers: number, 
  maxViewers: number
): number => {
  const timeBlock = Math.floor(Date.now() / 30000) // 30-second blocks
  const seed = productId.split("").reduce((acc, char, i) => 
    acc + char.charCodeAt(0) * (i + 1), 0
  ) + timeBlock

  // Simple seeded random
  const random = ((seed * 9301 + 49297) % 233280) / 233280
  return Math.floor(random * (maxViewers - minViewers + 1)) + minViewers
}

const UrgencyIndicator = ({
  productId,
  minViewers = 3,
  maxViewers = 15,
  className = "",
}: UrgencyIndicatorProps) => {
  const [viewerCount, setViewerCount] = useState<number | null>(null)
  const [mounted, setMounted] = useState(false)

  // Client-only to prevent hydration mismatch
  useEffect(() => {
    setMounted(true)
    setViewerCount(generateViewerCount(productId, minViewers, maxViewers))

    // Update every 30 seconds
    const interval = setInterval(() => {
      setViewerCount(generateViewerCount(productId, minViewers, maxViewers))
    }, 30000)

    return () => clearInterval(interval)
  }, [productId, minViewers, maxViewers])

  if (!mounted || viewerCount === null) {
    return null // Prevent hydration mismatch
  }

  return (
