class BundleModuleService extends MedusaService({ Bundle, BundleItem }) {

  // Calculate bundle prices (handles both pricing types)
  async calculateBundlePrice(bundleId: string): Promise<{
    originalPrice: number
    salePrice: number
    savings: number
    savingsPercent: number
  }> {
    const bundle = await this.retrieveBundle(bundleId, { relations: ['items'] })

    if (bundle.pricing_type === 'fixed') {
      return {
        originalPrice: bundle.fixed_original_price,
        salePrice: bundle.fixed_sale_price,
        savings: bundle.fixed_original_price - bundle.fixed_sale_price,
        savingsPercent: Math.round((1 - bundle.fixed_sale_price / bundle.fixed_original_price) * 100)
      }
    }

    // Percentage discount - calculate from component prices
    // Requires fetching variant prices from product module
    const componentTotal = await this.getComponentTotal(bundle.items)
    const salePrice = Math.round(componentTotal * (1 - bundle.discount_percentage / 100))

    return {
      originalPrice: componentTotal,
      salePrice,
      savings: componentTotal - salePrice,
      savingsPercent: bundle.discount_percentage
