import { defineMiddlewares } from "@medusajs/medusa"

describe("Upload Middleware Configuration", () => {
  it("should have body parser limit of at least 25mb for /admin/uploads", () => {
    const middlewares = require("../api/middlewares").default
    const uploadRoute = middlewares.routes.find(
      (r: any) => r.matcher === "/admin/uploads"
    )

    expect(uploadRoute).toBeDefined()
    expect(uploadRoute.bodyParser).toBeDefined()

    // Parse limit to bytes
    const limitStr = uploadRoute.bodyParser.sizeLimit
    const limitBytes = parseLimit(limitStr)

    expect(limitBytes).toBeGreaterThanOrEqual(25 * 1024 * 1024) // 25MB
  })

  it("should have body parser limit for /admin/uploads/* routes", () => {
    const middlewares = require("../api/middlewares").default
    const uploadSubRoute = middlewares.routes.find(
      (r: any) => r.matcher === "/admin/uploads/*"
    )

    expect(uploadSubRoute).toBeDefined()
    expect(uploadSubRoute.bodyParser.sizeLimit).toBeDefined()
  })
})

function parseLimit(limit: string): number {
  const match = limit.match(/^(\d+)(mb|kb|gb)?$/i)
  if (!match) return 0
  const num = parseInt(match[1])
  const unit = (match[2] || "b").toLowerCase()
  const multipliers: Record<string, number> = {
    b: 1,
    kb: 1024,
    mb: 1024 * 1024,
    gb: 1024 * 1024 * 1024,
  }
  return num * (multipliers[unit] || 1)
}
```

