    const fileModule = modules.find(
      (m: any) => m.resolve?.includes("file")
    )

    if (fileModule?.options?.providers) {
      const s3Provider = fileModule.options.providers.find(
        (p: any) => p.id === "s3"
      )

      // If s3_config_options exists, verify timeout
      if (s3Provider?.options?.s3_config_options) {
        const timeout = s3Provider.options.s3_config_options.requestTimeout
        expect(timeout).toBeGreaterThanOrEqual(60000) // At least 1 minute
      }
    }
  })
})
